import type { AvatarPackage } from '@naavos/schema';

import { renderContext } from '../context.js';
import type { FileMap } from '../index.js';

export function claudeCodeAdapter(pkg: AvatarPackage): FileMap {
  return new Map([
    [
      'CLAUDE.md',
      '# CLAUDE.md — NAAvOS Integration\n\n> Generated by NAAvOS. Recompile to update.\n\n' +
        renderContext(pkg),
    ],
  ]);
}
